  100 static int dispatch_audio(short *outbuf, int length, espeak_EVENT *event)
  101 {
  102 	int a_wave_can_be_played = 1;
  103 #ifdef USE_ASYNC
  104 	if ((my_mode & ENOUTPUT_MODE_SYNCHRONOUS) == 0)
  105 		a_wave_can_be_played = fifo_is_command_enabled();
  106 #endif
  107 
  108 	switch ((int)my_mode)
  109 	{
  110 	case ENOUTPUT_MODE_SPEAK_AUDIO:
  111 	case ENOUTPUT_MODE_SPEAK_AUDIO | ENOUTPUT_MODE_SYNCHRONOUS:
  112 	{
  113 		int event_type = 0;
  114 		if (event)
  115 			event_type = event->type;
  116 
  117 		if (event_type == espeakEVENT_SAMPLERATE) {
  118 			voice_samplerate = event->id.number;
  119 
  120 			if (out_samplerate != voice_samplerate) {
  121 #ifdef HAVE_PCAUDIOLIB_AUDIO_H
  122 				if (out_samplerate != 0) {
  123 					// sound was previously open with a different sample rate
  124 					audio_object_close(my_audio);
  125 					out_samplerate = 0;
  126 #ifdef HAVE_SLEEP
  127 					sleep(1);
  128 #endif
  129 				}
  130 #endif
  131 #ifdef HAVE_PCAUDIOLIB_AUDIO_H
  132 				int error = audio_object_open(my_audio, AUDIO_OBJECT_FORMAT_S16LE, voice_samplerate, 1);
  133 				if (error != 0) {
  134 					fprintf(stderr, "error: %s\n", audio_object_strerror(my_audio, error));
  135 					err = ENS_AUDIO_ERROR;
  136 					return -1;
  137 				}
  138 #endif
  139 				out_samplerate = voice_samplerate;
  140 #ifdef USE_ASYNC
  141 				if ((my_mode & ENOUTPUT_MODE_SYNCHRONOUS) == 0)
  142 					event_init();
  143 #endif
  144 			}
  145 		}
  146 
  147 #ifdef HAVE_PCAUDIOLIB_AUDIO_H
  148 		if (out_samplerate == 0) {
  149 			int error = audio_object_open(my_audio, AUDIO_OBJECT_FORMAT_S16LE, voice_samplerate, 1);
  150 			if (error != 0) {
  151 				fprintf(stderr, "error: %s\n", audio_object_strerror(my_audio, error));
  152 				err = ENS_AUDIO_ERROR;
  153 				return -1;
  154 			}
  155 			out_samplerate = voice_samplerate;
  156 		}
  157 #endif
  158 
  159 #ifdef HAVE_PCAUDIOLIB_AUDIO_H
  160 		if (outbuf && length && a_wave_can_be_played) {
  161 			int error = audio_object_write(my_audio, (char *)outbuf, 2*length);
  162 			if (error != 0)
  163 				fprintf(stderr, "error: %s\n", audio_object_strerror(my_audio, error));
  164 		}
  165 #endif
  166 
  167 #ifdef USE_ASYNC
  168 		while (event && a_wave_can_be_played) {
  169 			// TBD: some event are filtered here but some insight might be given
  170 			// TBD: in synthesise.cpp for avoiding to create WORDs with size=0.
  171 			// TBD: For example sentence "or ALT)." returns three words
  172 			// "or", "ALT" and "".
  173 			// TBD: the last one has its size=0.
  174 			if ((event->type == espeakEVENT_WORD) && (event->length == 0))
  175 				break;
  176 			if ((my_mode & ENOUTPUT_MODE_SYNCHRONOUS) == 0) {
  177 				err = event_declare(event);
  178 				if (err != ENS_EVENT_BUFFER_FULL)
  179 					break;
